/**
 * @publicApi
 */
export class RmqRecord {
    data;
    options;
    constructor(data, options) {
        this.data = data;
        this.options = options;
    }
}
/**
 * @publicApi
 */
export class RmqRecordBuilder {
    data;
    options;
    constructor(data) {
        this.data = data;
    }
    setOptions(options) {
        this.options = options;
        return this;
    }
    setData(data) {
        this.data = data;
        return this;
    }
    build() {
        return new RmqRecord(this.data, this.options);
    }
}
